import type {SidebarsConfig} from '@docusaurus/plugin-content-docs';

// One explicit sidebar. Every page appears in exactly one entry, and an entry is
// only added in the same commit as the page it names — never `autogenerated`,
// which hides orphans and reorders when a file is renamed.
const sidebars: SidebarsConfig = {
  docs: [
    'index',
    {
      type: 'category',
      label: 'Guides',
      items: ['guides/start'],
    },
  ],
};

export default sidebars;
